import sys, json
try:
    data = json.loads(sys.stdin.read())
except ValueError:
    raise SystemExit(1)
if not isinstance(data, dict):
    raise SystemExit(1)
if "name" in data and not isinstance(data["name"],str):
    raise SystemExit(1)
def greeting(form):
    name = form.get("name", "").strip()
    return "missing" if not name else f"hello {name}"
print(greeting(data))
